create or replace function public.layer2_evidence_capacity_status() returns jsonb language sql stable security definer set search_path = pg_catalog, pipeline, storage as $$ with usage as (select count(*)::bigint objects, coalesce(sum((metadata->>'size')::bigint),0)::bigint bytes from storage.objects where bucket_id='evidence'), p as (select * from pipeline.evidence_capacity_policy where id=true), x as (select u.objects,u.bytes,p.planning_capacity_bytes,p.warn_pct,p.high_pct,p.critical_pct,p.capacity_basis, case when p.planning_capacity_bytes=0 then 0 else (u.bytes::numeric*100/p.planning_capacity_bytes) end pct from usage u cross join p) select jsonb_build_object('objects',objects,'bytes',bytes,'planning_capacity_bytes',planning_capacity_bytes,'used_pct',round(pct,2),'warn_pct',warn_pct,'high_pct',high_pct,'critical_pct',critical_pct,'state',case when pct>=critical_pct then 'critical' when pct>=high_pct then 'high' when pct>=warn_pct then 'warn' else 'normal' end,'capacity_basis',capacity_basis) from x; $$; revoke all on function public.layer2_evidence_capacity_status() from public, anon, authenticated; grant execute on function public.layer2_evidence_capacity_status() to service_role;
